def transform(grid):
    from collections import Counter

    # Count occurrences of each color to determine the background color
    counts = Counter()
    for row in grid:
        for cell in row:
            counts[cell] = counts.get(cell, 0) + 1

    grid_background = max(counts, key=counts.get)

    result = []
    for row in grid:
        # Check if the row is uniform (contains only one unique color)
        # If uniform, it stays the same regardless of background
        if row.count(grid_background) == len(row):
            result.append(list(row))
        else:
            # Mixed row: Replace the trailing background segment with 1
            # Convert row to list for manipulation
            r = list(row)

            # Find the length of the contiguous background segment at the end of the row
            bg_suffix_len = 0
            for i in range(len(r) - 1, -1, -1):
                if r[i] == grid_background:
                    bg_suffix_len += 1
                else:
                    break

            # In a mixed row, the suffix background (which is not all the row) changes to 1
            if bg_suffix_len > 0:
                for i in range(len(r) - bg_suffix_len, len(r)):
                    r[i] = 1

            result.append(r)

    return result
